import SwiftUI
struct DashboardView:View{@EnvironmentObject var session:SessionStore;var body:some View{NavigationStack{ZStack{LinearGradient(colors:[.black,Color(red:0.02,green:0.10,blue:0.06)],startPoint:.top,endPoint:.bottom).ignoresSafeArea();ScrollView{VStack(alignment:.leading,spacing:18){Text("FRONT OFFICE").font(.largeTitle.bold());Text(session.leagueConnected ? session.leagueName.uppercased():"AI FANTASY GM").font(.caption.bold()).foregroundStyle(.green);if session.leagueConnected{GroupBox{HStack{VStack(alignment:.leading){Text(session.teamName).font(.title2.bold());Text(session.recordText).foregroundStyle(.secondary)};Spacer();if let r=session.rank{Text("#\(r)").font(.system(size:36,weight:.black)).foregroundStyle(.green)}}};Button("Refresh ESPN Data"){Task{await session.refresh()}}.buttonStyle(.borderedProminent).tint(.green)}else{Text("Connect your ESPN league once, then use the app as your daily fantasy dashboard.").foregroundStyle(.secondary);NavigationLink("CONNECT ESPN LEAGUE"){ESPNConnectView()}.buttonStyle(.borderedProminent).tint(.green)}}.padding()}}.refreshable{await session.refresh()}}}
struct MyTeamView:View{@EnvironmentObject var session:SessionStore;var body:some View{NavigationStack{List(session.players){p in HStack(spacing:14){ZStack{Circle().fill(.green.opacity(0.16)).frame(width:54,height:54);Text(p.fantasyOVR.map(String.init) ?? "—").font(.headline.bold()).foregroundStyle(.green)};VStack(alignment:.leading){Text(p.name).font(.headline);Text([p.position,p.lineupSlot].compactMap{$0}.joined(separator:" · ")).foregroundStyle(.secondary);if let pts=p.totalPoints{Text(String(format:"%.1f pts · Fantasy OVR %@",pts,p.fantasyOVR.map(String.init) ?? "—")).font(.caption).foregroundStyle(.secondary)}}}}.navigationTitle("My Team").refreshable{await session.refresh()}.overlay{if session.players.isEmpty{ContentUnavailableView("No roster loaded",systemImage:"person.3",description:Text("Connect ESPN from Home to import your team."))}}}}}
struct ESPNConnectView:View{@EnvironmentObject var session:SessionStore;@Environment(\.dismiss)var dismiss;@State private var c=ESPNConnection();var body:some View{Form{Section("League"){TextField("League ID",text:$c.leagueID).keyboardType(.numberPad);TextField("Team ID",text:$c.teamID).keyboardType(.numberPad);TextField("Season",text:$c.season).keyboardType(.numberPad)};Section("Private ESPN league"){SecureField("espn_s2",text:$c.espnS2);SecureField("SWID",text:$c.swid);Text("Used only to read your private ESPN league.").font(.caption).foregroundStyle(.secondary)};if let e=session.errorMessage{Section{Text(e).foregroundStyle(.red)}};Section{Button(session.isLoading ? "Importing…":"Test & Import"){Task{if await session.connect(c){dismiss()}}}.disabled(session.isLoading || c.leagueID.isEmpty)}}.navigationTitle("Connect ESPN")}}
struct WaiversView:View{@EnvironmentObject var session:SessionStore;@State private var players:[FantasyPlayer]=[];@State private var error:String?;var body:some View{NavigationStack{List(players){p in VStack(alignment:.leading){Text(p.name).font(.headline);Text("\(p.position) · \(String(format:"%.1f",p.totalPoints ?? 0)) pts").foregroundStyle(.secondary)}}.navigationTitle("Waivers").task{await load()}.refreshable{await load()}.overlay{if players.isEmpty && error==nil{ContentUnavailableView("Waiver Wire",systemImage:"magnifyingglass",description:Text("Connect ESPN to see available players."))}}}};func load()async{guard let t=session.token else{return};do{players=try await APIClient.shared.waivers(token:t).players}catch{self.error=error.localizedDescription}}}
struct AIGMView:View{@EnvironmentObject var session:SessionStore;@State private var prompt="",answer="";@State private var loading=false;var body:some View{NavigationStack{VStack{ScrollView{if answer.isEmpty{ContentUnavailableView("AI General Manager",systemImage:"sparkles",description:Text("Ask about trades, starts, drops, or waiver targets using your live ESPN league."))}else{Text(answer).frame(maxWidth:.infinity,alignment:.leading).padding()}};HStack{TextField("Ask your GM…",text:$prompt).textFieldStyle(.roundedBorder);Button{Task{await send()}}label:{Image(systemName:"arrow.up.circle.fill").font(.title).foregroundStyle(.green)}}.padding()}.navigationTitle("AI GM")}};func send()async{guard let t=session.token,!prompt.isEmpty else{return};loading=true;do{answer=try await APIClient.shared.askGM(prompt,token:t).answer;prompt=""}catch{answer=error.localizedDescription};loading=false}}
struct SettingsView:View{@EnvironmentObject var session:SessionStore;var body:some View{NavigationStack{Form{Section("ESPN"){LabeledContent("League",value:session.leagueName.isEmpty ? "Not connected":session.leagueName)};Section("Account"){Button("Sign Out",role:.destructive){session.signOut()}};Section("About"){LabeledContent("App",value:"AI Fantasy GM");LabeledContent("Client",value:"Native iOS")}}.navigationTitle("Settings")}}}
